def L(id, moves, diff, tiles, obstacles, objectives, name, desc, theme, floor, stars=(24000, 32000), intro=None):
    if id in TUNE:
        moves, tt, obs, stars = TUNE[id]
        objectives = [(o, k, obs[k] if k in obs else (n if k in ('crate', 'ice', 'chain', 'key') else tt))
                      for o, k, n in objectives]
    d = dict(id=id, moves=moves, diff=diff, tiles=tiles, obstacles=obstacles, objectives=objectives,
             name=name, desc=desc, theme=theme, floor=floor, stars=list(stars),
             scene=SCENES.get(id) or _placeholder(objectives))
    if intro:
        d['obstacle_intro'] = intro
    return d


